def route_pallet(n):
    if n % 12 == 0:          # 12 = lcm(3, 4): both belts at once
        return "priority-dock"
    if n % 3 == 0:
        return "belt-east"
    if n % 4 == 0:
        return "belt-west"
    return "manual-check"

