def count_sweep(w, h, p, q):
    covered = 0
    for x in range(1, w + 1):
        for y in range(1, h + 1):
            if q * y <= p * x:
                covered += 1
            else:
                break  # higher tiles in this column are even further past the line
    return covered

def cycles_to_seal(n):
    cycles = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        cycles += 1
    return cycles

def transmission(seed, n):
    term = seed
    for _ in range(n - 1):
        parts = []
        i = 0
        while i < len(term):
            j = i
            while j < len(term) and term[j] == term[i]:
                j += 1
            parts.append(str(j - i) + term[i])  # count, then digit
            i = j
        term = "".join(parts)
    return term
